package com.player.interpreter.domain.commands;

import com.player.interpreter.domain.JFugueTokenFactory;
import com.player.interpreter.domain.MusicalDuration;
import java.util.Objects;

/**
 * Represents the musical token generated by executing a domain command.
 *
 * <p>Encapsulates the formatted JFugue token string and its sounding musical duration, avoiding the
 * need to parse raw token strings via regular expressions.
 *
 * @param token the JFugue token string
 * @param duration the sounding musical duration, or {@code null} if non-sounding
 */
public record SoundToken(String token, MusicalDuration duration) {

  /** An empty sound token representing a command with no audible or control output. */
  public static final SoundToken EMPTY = new SoundToken("", null);

  /**
   * Constructs a {@code SoundToken} verifying non-null token string.
   *
   * @param token the JFugue token string
   * @param duration the sounding musical duration, or {@code null} if non-sounding
   */
  public SoundToken {
    Objects.requireNonNull(token, "token cannot be null");
  }

  /**
   * Creates a non-sounding token (such as a tempo or instrument control).
   *
   * @param token the formatted JFugue control token string
   * @return a new {@link SoundToken} without a musical duration
   */
  public static SoundToken of(final String token) {
    return new SoundToken(token, null);
  }

  /**
   * Creates a sounding token with an explicit musical duration.
   *
   * @param token the formatted JFugue token string
   * @param duration the musical duration
   * @return a new sounding {@link SoundToken}
   */
  public static SoundToken of(final String token, final MusicalDuration duration) {
    return new SoundToken(token, duration);
  }

  /**
   * Creates a quarter-note rest token.
   *
   * @return a {@link SoundToken} representing a silence
   */
  public static SoundToken rest() {
    return new SoundToken(JFugueTokenFactory.rest(), MusicalDuration.QUARTER_NOTE);
  }

  /**
   * Indicates whether this token produces sound on the timeline.
   *
   * @return {@code true} if this token has a musical duration, {@code false} otherwise
   */
  public boolean isSound() {
    return duration != null;
  }
}
